// Mando, drawn from the firmware's own sprites (MandoSprites, generated by scripts/export_mando.py): pixel
// art scaled up without smoothing, for the empty and error states, and the 11 x 9 head for the menu bar.

import AppKit
import SwiftUI

struct MandoFrame: Sendable {
    let width: Int
    let height: Int
    let hex: String

    /// One colour index per pixel, 0 for clear.
    var pixels: [UInt8] {
        let digits = hex.compactMap { $0.hexDigitValue }.map(UInt8.init)
        return Array(digits.prefix(width * height))
    }
}

enum MandoPose: CaseIterable {
    case review, wait, think, hop, doze

    var frame: MandoFrame {
        switch self {
        case .review: return MandoSprites.review
        case .wait: return MandoSprites.wait
        case .think: return MandoSprites.think
        case .hop: return MandoSprites.hop
        case .doze: return MandoSprites.doze
        }
    }
}

enum MandoArt {
    /// An RGBA image of a frame, one image pixel per sprite pixel.
    static func image(_ frame: MandoFrame) -> CGImage? {
        let rgba = frame.pixels.flatMap { index -> [UInt8] in
            guard index > 0, Int(index) <= MandoSprites.colours.count else { return [0, 0, 0, 0] }
            let rgb = MandoSprites.colours[Int(index) - 1]
            return [UInt8((rgb >> 16) & 0xFF), UInt8((rgb >> 8) & 0xFF), UInt8(rgb & 0xFF), 255]
        }
        return cgImage(rgba, width: frame.width, height: frame.height)
    }

    /// The head as a template: the fur opaque, the eyes and nose (0x13) cut out.
    static func headTemplate() -> CGImage? {
        let rgba = MandoSprites.head.flatMap { entry -> [UInt8] in
            entry == 0 || entry == 0x13 ? [0, 0, 0, 0] : [0, 0, 0, 255]
        }
        return cgImage(rgba, width: 11, height: 9)
    }

    /// The head in Mando's colours, the eyes and nose in the dark of the device's OnAccent.
    static func head() -> CGImage? {
        let rgba = MandoSprites.head.flatMap { entry -> [UInt8] in
            if entry == 0x13 {
                return [0x1D, 0x13, 0x0B, 255]
            }
            let index = Int(entry) - 0x20
            guard entry != 0, MandoSprites.colours.indices.contains(index) else { return [0, 0, 0, 0] }
            let rgb = MandoSprites.colours[index]
            return [UInt8((rgb >> 16) & 0xFF), UInt8((rgb >> 8) & 0xFF), UInt8(rgb & 0xFF), 255]
        }
        return cgImage(rgba, width: 11, height: 9)
    }

    static func cgImage(_ rgba: [UInt8], width: Int, height: Int) -> CGImage? {
        guard let provider = CGDataProvider(data: Data(rgba) as CFData) else { return nil }
        return CGImage(width: width, height: height, bitsPerComponent: 8, bitsPerPixel: 32, bytesPerRow: width * 4,
                       space: CGColorSpace(name: CGColorSpace.sRGB) ?? CGColorSpaceCreateDeviceRGB(),
                       bitmapInfo: CGBitmapInfo(rawValue: CGImageAlphaInfo.last.rawValue), provider: provider,
                       decode: nil, shouldInterpolate: false, intent: .defaultIntent)
    }

    static let cache: [MandoPose: CGImage] = Dictionary(uniqueKeysWithValues: MandoPose.allCases.compactMap { pose in
        image(pose.frame).map { (pose, $0) }
    })
}

/// Mando at `scale` points per sprite pixel.
struct MandoView: View {
    let pose: MandoPose
    var scale: CGFloat = 2

    var body: some View {
        let frame = pose.frame
        Group {
            if let image = MandoArt.cache[pose] {
                Image(decorative: image, scale: 1).resizable().interpolation(.none)
            } else {
                Color.clear
            }
        }
        .frame(width: CGFloat(frame.width) * scale, height: CGFloat(frame.height) * scale)
        .accessibilityHidden(true)
    }
}

/// Mando's 11 x 9 head (the device's status bar head), `scale` points per pixel.
struct MandoHeadView: View {
    var scale: CGFloat = 3

    var body: some View {
        Group {
            if let image = MandoArt.head() {
                Image(decorative: image, scale: 1).resizable().interpolation(.none)
            }
        }
        .frame(width: 11 * scale, height: 9 * scale)
        .accessibilityHidden(true)
    }
}
